enum Route: Hashable, Codable { case product(id: String), cart, checkout }

@Observable @MainActor
final class Router {
    var path: [Route] = []
    func show(_ route: Route) { path.append(route) }
    func popToRoot() { path.removeAll() }
    func handle(_ url: URL) {            // myshop://product/42
        if url.host == "product" { path = [.product(id: url.lastPathComponent)] }
        else if url.host == "cart" { path = [.cart] }
    }
}

struct RootView: View {
    @State private var router = Router()
    var body: some View {
        NavigationStack(path: $router.path) {
            HomeView()
                .navigationDestination(for: Route.self) { route in
                    switch route {
                    case .product(let id): ProductView(id: id)
                    case .cart:            CartView()
                    case .checkout:        CheckoutView()
                    }
                }
        }
        .environment(router)
        .onOpenURL { router.handle($0) }
    }
}
